def read_rainbow_table(password_hashes):
    """Read rainbow table for passwords matching provided hashes."""
    rainbow_table = []
    for hash in password_hashes:
        salt = hash[:32]
        hash = hashlib.sha256(salt.encode()).hexdigest()
        rainbow_table.append(hash)

    return rainbow_table

